def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    from heapq import heappop, heappush

    times = sorted({time for start, end, _ in jobs for time in (start, end)})
    index = {time: i for i, time in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, capacity, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest distances are computed in time order because all
    # initially usable edges point forward.
    inf = float("inf")
    potential = [inf] * n
    potential[0] = 0
    for u in range(n):
        for v, capacity, cost, _ in graph[u]:
            if capacity and potential[v] > potential[u] + cost:
                potential[v] = potential[u] + cost

    total_cost = 0
    flow = 0

    while flow < k:
        dist = [inf] * n
        dist[0] = 0
        previous = [None] * n
        heap = [(0, 0)]

        while heap:
            current_dist, u = heappop(heap)
            if current_dist != dist[u]:
                continue
            for edge_index, (v, capacity, cost, _) in enumerate(graph[u]):
                if capacity:
                    new_dist = current_dist + cost + potential[u] - potential[v]
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        previous[v] = (u, edge_index)
                        heappush(heap, (new_dist, v))

        for v in range(n):
            if dist[v] < inf:
                potential[v] += dist[v]

        amount = k - flow
        v = n - 1
        while v:
            u, edge_index = previous[v]
            amount = min(amount, graph[u][edge_index][1])
            v = u

        v = n - 1
        while v:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            total_cost += amount * edge[2]
            edge[1] -= amount
            graph[v][edge[3]][1] += amount
            v = u

        flow += amount

    return -total_cost
